@Service @Transactional
public class CustomerMasterService {
 private final JdbcTemplate jdbc;private final AuthorizationService auth;private final FieldPolicyService fields;private final AuditWriter audit;private final IdempotencyExecutor idem;private final JsonCodec json;private final BankAccountCipher cipher;
 public CustomerMasterService(JdbcTemplate jdbc,AuthorizationService auth,FieldPolicyService fields,AuditWriter audit,IdempotencyExecutor idem,JsonCodec json,DocumentAccessService documents,BankAccountCipher cipher){this.jdbc=jdbc;this.auth=auth;this.fields=fields;this.audit=audit;this.idem=idem;this.json=json;this.cipher=cipher;
  var read=List.of("md:customer:view","md:customer:edit","sal:order:view","sal:order:create","sal:outbound:create","sal:outbound:confirm","sal:order:submit","ar:credit-rule:view","ar:credit-rule:edit","ar:receipt:create","ar:receipt:view","ar:writeoff:create","ar:writeoff:view","ar:statement:view","rtn:sales:create","rtn:sales:view","rtn:refund:create","rtn:refund:view");for(String type:List.of("CUSTOMER","MD_CUSTOMER"))documents.register(type,read,List.of("md:customer:edit"),(a,id)->{try{return row(a,"customers",id,false);}catch(ApiException e){if(e.getStatus()==404)return null;throw e;}},(a,id)->jdbc.queryForList("SELECT id FROM md_customer WHERE country_id=? AND id=? FOR UPDATE",a.requireCountry(),id));
 }
 public Object list(RequestContext c,String kind,Map<String,String> q){var a=auth.authorize(c);a.require("md:customer:view","md:customer:edit");List<Object> args=new ArrayList<>();args.add(a.requireCountry());String table=table(kind),where="c.country_id=?";if(kind.equals("customers"))where+=" AND "+scope(a,"c.store_id",args);if(q.get("status")!=null){where+=" AND c.status=?";args.add(q.get("status"));}if(q.get("keyword")!=null&&!q.get("keyword").isBlank()){where+=" AND (c.code ILIKE ? OR c.name ILIKE ?)";args.add("%"+q.get("keyword")+"%");args.add("%"+q.get("keyword")+"%");}if(kind.equals("customers"))for(String filter:List.of("groupId","levelId","storeId"))if(q.get(filter)!=null){where+=" AND c."+filter.replaceAll("([a-z])([A-Z])","$1_$2").toLowerCase(Locale.ROOT)+"=?";args.add(Inputs.id(new java.math.BigDecimal(q.get(filter))));}int page=page(q.get("page"),1,1000000),size=page(q.get("size"),20,200);long total=jdbc.queryForObject("SELECT count(*) FROM "+table+" c WHERE "+where,Long.class,args.toArray());args.add(size);args.add((page-1)*size);var rows=jdbc.queryForList("SELECT c.* FROM "+table+" c WHERE "+where+" ORDER BY c.id DESC LIMIT ? OFFSET ?",args.toArray()).stream().map(DbRows::camel).map(r->output(a,kind,r)).toList();return Map.of("records",rows,"total",total,"page",page,"size",size);}
 public Map<String,Object> get(RequestContext c,String kind,long id){var a=auth.authorize(c);a.require("md:customer:view","md:customer:edit");return output(a,kind,row(a,kind,id,false));}
 public Map<String,Object> save(RequestContext c,String kind,Long id,Map<String,Object> b,String key){var a=auth.authorize(c);a.require("md:customer:edit");return idem.execute(c,id==null?"POST":"PUT","/api/v1/md/"+kind+(id==null?"":"/"+id),key,b,null,()->{var old=id==null?null:row(a,kind,id,true);if(old!=null&&Inputs.version(b)!=n(old,"version"))throw Inputs.conflict();String code=Inputs.required(b,"code"),name=Inputs.required(b,"name"),status=Inputs.text(b,"status",old==null?"ENABLED":String.valueOf(old.get("status")));if(!Set.of("ENABLED","DISABLED").contains(status))throw Inputs.bad("客户档案状态不合法");long resultId;if(kind.equals("customers")){Long store=optionalId(b,"storeId",old);if(store==null&&!a.scope().all()){store=a.scope().stores().stream().min(Long::compareTo).orElseThrow(ApiException::notFound);}if(store!=null&&!a.scope().all()&&!a.scope().stores().contains(store))throw ApiException.notFound();Long owner=optionalId(b,"salesOwnerId",old);if(owner!=null&&jdbc.queryForObject("SELECT count(*) FROM sys_user u JOIN sys_user_role ur ON ur.user_id=u.id WHERE u.id=? AND ur.country_id=? AND u.status='ENABLED'",Integer.class,owner,a.requireCountry())==0)throw Inputs.bad("销售负责人未获本国授权");Object addresses=b.getOrDefault("addresses",old==null?List.of():old.get("addresses"));if(!(addresses instanceof List<?>))throw Inputs.bad("客户地址必须为列表");if(id==null)resultId=jdbc.queryForObject("INSERT INTO md_customer(country_id,code,name,group_id,level_id,store_id,sales_owner_id,contact,phone,email,tax_id,addresses,remark,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?::jsonb,?,?) RETURNING id",Long.class,a.requireCountry(),code,name,optionalId(b,"groupId",old),optionalId(b,"levelId",old),store,owner,Inputs.text(b,"contact",""),Inputs.text(b,"phone",""),Inputs.text(b,"email",""),Inputs.text(b,"taxId",""),json.write(addresses),Inputs.text(b,"remark",""),status);else{resultId=id;jdbc.update("UPDATE md_customer SET code=?,name=?,group_id=?,level_id=?,store_id=?,sales_owner_id=?,contact=?,phone=?,email=?,tax_id=?,addresses=?::jsonb,remark=?,status=?,version=version+1,updated_at=clock_timestamp() WHERE country_id=? AND id=?",code,name,optionalId(b,"groupId",old),optionalId(b,"levelId",old),store,owner,text(b,"contact",old),text(b,"phone",old),text(b,"email",old),text(b,"taxId",old),json.write(addresses),text(b,"remark",old),status,a.requireCountry(),id);}}
  else{if(id==null)resultId=jdbc.queryForObject("INSERT INTO "+table(kind)+"(country_id,code,name,status) VALUES(?,?,?,?) RETURNING id",Long.class,a.requireCountry(),code,name,status);else{resultId=id;jdbc.update("UPDATE "+table(kind)+" SET code=?,name=?,status=?,version=version+1 WHERE country_id=? AND id=?",code,name,status,a.requireCountry(),id);}}
  var result=output(a,kind,row(a,kind,resultId,false));audit.append(c,"维护客户档案","MD_CUSTOMER",resultId,old,result);return result;},r->row(a,kind,n(r,"id"),false));}
 public Map<String,Object> toggle(RequestContext c,String kind,long id,boolean enabled,Map<String,Object> b,String key){var a=auth.authorize(c);a.require("md:customer:edit");return idem.execute(c,"POST","/api/v1/md/"+kind+"/"+id+"/"+(enabled?"enable":"disable"),key,b,null,()->{var old=row(a,kind,id,true);if(Inputs.version(b)!=n(old,"version"))throw Inputs.conflict();jdbc.update("UPDATE "+table(kind)+" SET status=?,version=version+1 WHERE country_id=? AND id=?",enabled?"ENABLED":"DISABLED",a.requireCountry(),id);var result=output(a,kind,row(a,kind,id,false));audit.append(c,"客户档案状态","MD_CUSTOMER",id,old,result);return result;},r->row(a,kind,id,false));}
 public Object banks(RequestContext c,long customer){var a=auth.authorize(c);a.require("md:customer:view");row(a,"customers",customer,false);if(FieldPolicyService.rank(a.fieldGroups().get("BANK_INFO"))<1)throw ApiException.forbidden();var rows=jdbc.queryForList("SELECT id,country_id,customer_id,bank_name,account_name,account_no_masked,bank_address,swift_code,currency,is_default,status,version FROM md_customer_bank WHERE country_id=? AND customer_id=? ORDER BY id",a.requireCountry(),customer).stream().map(DbRows::camel).map(r->fields.mask(a,r,"BANK_INFO")).toList();audit.append(c,"查看客户银行信息","CUSTOMER",customer,null,null);return rows;}
 public Map<String,Object> saveBank(RequestContext c,long customer,Long id,Map<String,Object> b,String key){var a=auth.authorize(c);a.require("md:customer:edit");row(a,"customers",customer,false);fields.requireWrite(a,b,"BANK_INFO");if(FieldPolicyService.rank(a.fieldGroups().get("BANK_INFO"))<2)throw ApiException.forbidden();return idem.execute(c,id==null?"POST":"PUT","/api/v1/md/customers/"+customer+"/banks"+(id==null?"":"/"+id),key,b,null,()->{row(a,"customers",customer,true);Map<String,Object> old=null;if(id!=null){var oldRows=jdbc.queryForList("SELECT * FROM md_customer_bank WHERE country_id=? AND customer_id=? AND id=? FOR UPDATE",a.requireCountry(),customer,id);if(oldRows.isEmpty())throw ApiException.notFound();old=oldRows.getFirst();if(Inputs.version(b)!=n(old,"version"))throw Inputs.conflict();}String raw=Inputs.text(b,"accountNo",null),masked=raw==null?Inputs.text(b,"accountNoMasked",old==null?"":String.valueOf(old.get("account_no_masked"))):"**** "+raw.substring(Math.max(0,raw.length()-4));String encrypted=raw==null?old==null?null:(String)old.get("account_no_encrypted"):cipher.encrypt(raw);String currency=Inputs.required(b,"currency");if(jdbc.queryForObject("SELECT count(*) FROM md_currency WHERE code=? AND status='ENABLED'",Integer.class,currency)!=1)throw Inputs.bad("银行账户币种未启用");long bank;if(id==null)bank=jdbc.queryForObject("INSERT INTO md_customer_bank(country_id,customer_id,bank_name,account_name,account_no_masked,account_no_encrypted,bank_address,swift_code,currency,is_default) VALUES(?,?,?,?,?,?,?,?,?,?) RETURNING id",Long.class,a.requireCountry(),customer,Inputs.required(b,"bankName"),Inputs.required(b,"accountName"),masked,encrypted,Inputs.text(b,"bankAddress",""),Inputs.text(b,"swiftCode",""),currency,Boolean.TRUE.equals(b.get("isDefault")));else{bank=id;jdbc.update("UPDATE md_customer_bank SET bank_name=?,account_name=?,account_no_masked=?,account_no_encrypted=?,bank_address=?,swift_code=?,currency=?,is_default=?,version=version+1 WHERE country_id=? AND customer_id=? AND id=?",Inputs.required(b,"bankName"),Inputs.required(b,"accountName"),masked,encrypted,Inputs.text(b,"bankAddress",""),Inputs.text(b,"swiftCode",""),currency,Boolean.TRUE.equals(b.get("isDefault")),a.requireCountry(),customer,id);}var result=DbRows.camel(jdbc.queryForMap("SELECT id,country_id,customer_id,bank_name,account_name,account_no_masked,bank_address,swift_code,currency,is_default,status,version FROM md_customer_bank WHERE country_id=? AND id=?",a.requireCountry(),bank));audit.append(c,"维护客户银行信息","CUSTOMER",customer,null,result);return result;},r->row(a,"customers",customer,false));}
 private Map<String,Object> row(Access a,String kind,long id,boolean lock){List<Object> args=new ArrayList<>();args.add(a.requireCountry());args.add(id);String where="country_id=? AND id=?";if(kind.equals("customers"))where+=" AND "+scope(a,"store_id",args);var rows=jdbc.queryForList("SELECT * FROM "+table(kind)+" WHERE "+where+(lock?" FOR UPDATE":""),args.toArray());if(rows.isEmpty())throw ApiException.notFound();var row=DbRows.camel(rows.getFirst());if(kind.equals("customers"))row.put("addresses",json.read(String.valueOf(row.get("addresses")),List.class));return row;}
 private Map<String,Object> output(Access a,String kind,Map<String,Object> row){row=new LinkedHashMap<>(row);if(kind.equals("customers")&&row.get("addresses") instanceof String text)row.put("addresses",json.read(text,List.class));return fields.mask(a,row,"CUSTOMER_PRICE");}
 private static String table(String kind){return switch(kind){case "customers"->"md_customer";case "customer-groups"->"md_customer_group";case "customer-levels"->"md_customer_level";default->throw ApiException.notFound();};}
 private static String scope(Access a,String col,List<Object> args){if(a.scope().all())return "TRUE";if(a.scope().stores().isEmpty())return "FALSE";args.addAll(a.scope().stores());return col+" IN ("+String.join(",",Collections.nCopies(a.scope().stores().size(),"?"))+")";}
 private static long n(Map<String,Object> row,String key){return ((Number)row.get(key)).longValue();}
 private static Long optionalId(Map<String,Object> b,String key,Map<String,Object> old){Object v=b.containsKey(key)?b.get(key):old==null?null:old.get(key);return v==null?null:Inputs.id(v);}
 private static String text(Map<String,Object> b,String key,Map<String,Object> old){return Inputs.text(b,key,old==null?"":String.valueOf(old.get(key)));}
 private static int page(String raw,int fallback,int max){if(raw==null)return fallback;try{int p=Integer.parseInt(raw);if(p<1||p>max)throw Inputs.bad("分页参数不合法");return p;}catch(NumberFormatException e){throw Inputs.bad("分页参数不合法");}}
}
